        pts=[(r,c) for r in range(64) for c in range(64) if rows[r][c]==L]
        if not pts: out[L]=[]; continue
        groups=[]
        for (r,c) in pts:
            for g in groups:
                if any(abs(r-a)+abs(c-b)<=2 for a,b in g):
                    g.append((r,c)); break
            else: groups.append([(r,c)])
